import {CHANNELS,renderChannelAudit,channelNote,sourceProducts} from './channel-audit.js?v=20261028-weather-v1';
export function createImportView(api) {
  const {$,$$,esc,nf,won,sum,getAnalysis,download,csvCell,rerender}=api;
  let kind='products',from='2026-01-01',to='2026-10-28',period='2026-07-01',query='',category='',sort='sales',page=0,channel='all',auditExpanded=false,layout='category';
  const imported=()=>getAnalysis().importSources||[];
  function rows() {
    const original=getAnalysis(),a={...original,products:sourceProducts(original.products,api.getChannels?.()).map(r=>api.catalog?.()?.row(r)||r),options:(original.options||[]).map(r=>api.catalog?.()?.row(r)||r)};
    return kind==='options'?(a.options||[]).filter(r=>r.start===period):a.products.filter(r=>r.date>=from&&r.date<=to);
  }
  function filtered(raw=rows()) {return raw.filter(r=>(kind==='options'||channel==='all'||r.channel===channel)&&(!category||r.category===category)&&[r.name,r.category,r.option,r.originalName,r.originalCategory].join(' ').toLowerCase().includes(query.toLowerCase()))}
  function group(raw) {
    if(kind==='options')return raw;
    const map=new Map();
    for(const r of raw){const key=r.productId||JSON.stringify([r.category,r.name]);if(!map.has(key))map.set(key,{productId:r.productId,category:r.category,name:r.name,qty:0,sales:0,gross:0,discount:0,refund:0,refundQty:0,points:0,prepaid:0,days:new Set(),names:new Set(),categories:new Set(),channels:{},unknownQty:false,unknownGross:false,unknownDiscount:false});const g=map.get(key);for(const k of ['qty','sales','gross','discount','refund','refundQty','points','prepaid'])g[k]+=r[k]||0;g.channels[r.channel||'payhere']=(g.channels[r.channel||'payhere']||0)+r.sales;g.unknownQty ||= !!r.unknownQty;g.unknownGross ||= r.gross===null;g.unknownDiscount ||= r.discount===null;g.days.add(r.date);g.names.add(r.originalName||r.name);g.categories.add(r.originalCategory||r.category)}
    return [...map.values()];
  }
  function optionRanking(product){
    if(!/젤라또|아이스크림|피자|하프|half|gelato|pizza/i.test([product.name,product.category,...product.names].join(' ')))return '';
    const matches=(getAnalysis().options||[]).map(r=>api.catalog?.()?.row(r)||r).filter(r=>(product.productId&&r.productId===product.productId)||product.names.has(r.originalName||r.name)||r.name===product.name);
    const periods=new Map();for(const r of matches){if(r.end<from||r.start>to)continue;const key=r.start+' ~ '+r.end;if(!periods.has(key))periods.set(key,new Map());const m=periods.get(key),name=r.option.trim();if(!m.has(name))m.set(name,0);m.set(name,m.get(name)+r.selections)}
    return `<div class="option-ranking"><h4>옵션별 순위 · 선택 판매량</h4><p>POS 옵션 원본 기준입니다. 세트·복수 맛은 한 상품에서 여러 옵션이 선택될 수 있어 상품 판매수량과 다릅니다. 배달·네이버 옵션은 미포함입니다.</p>${periods.size?[...periods].map(([period,rows])=>`<h5>${esc(period)} 누적</h5><p>조회 기간에 걸치는 원본 전체 기간입니다. 일별 자료가 없어 선택 기간으로 나누지 않습니다.</p><table><thead><tr><th>순위</th><th>옵션</th><th>선택 수량</th></tr></thead><tbody>${[...rows].sort((a,b)=>b[1]-a[1]).map(([name,n],i)=>`<tr><td>${i+1}</td><td>${esc(name)}</td><td>${nf(n)}개</td></tr>`).join('')}</tbody></table>`).join(''):'<p>이 상품에 연결되는 옵션 원본이 없습니다.</p>'}</div>`;
  }
  function productRow(r,total,index){
    const share=total>0?r.sales/total*100:0;
    return `<tr><td><span class="product-rank">${index+1}</span><strong>${esc(r.name)}</strong><small class="table-sub">${esc(r.category)} · 판매 기록 ${nf(r.days.size)}일</small></td><td class="num product-sales"><strong>${won(r.sales)}</strong></td><td class="num">${nf(r.qty)}<small class="table-sub">${r.unknownQty?'미확인 수량 별도':'개'}</small></td><td class="num"><span>${share.toFixed(1)}%</span><div class="product-share"><i style="width:${Math.min(100,Math.max(0,share))}%"></i></div></td><td><details class="product-breakdown"><summary>상세 보기</summary><dl><dt>채널별 상품액</dt><dd>${Object.entries(r.channels).map(([c,v])=>`<span>${CHANNELS[c]} <b>${won(v)}</b></span>`).join('')}</dd><dt>할인 전 총매출</dt><dd>${r.unknownGross?(r.gross?won(r.gross)+' + 미제공':'미제공'):won(r.gross)}</dd><dt>확인 할인액</dt><dd>${r.unknownDiscount?(r.discount?won(r.discount)+' + 미제공':'미제공'):won(r.discount)}</dd><dt>환불 별도 표시</dt><dd>${won(r.refund)} · ${nf(r.refundQty)}개</dd><dt>포인트 / 선불권</dt><dd>${won(r.points)} / ${won(r.prepaid)}</dd><dt>통합 전 원본명 ${r.names.size}개</dt><dd>${[...r.names].map(n=>`<span>${esc(n)}</span>`).join('')}</dd></dl>${optionRanking(r)}</details></td></tr>`;
  }
  function productTable(rs,total){return `<div class="table-wrap"><table class="readable-products"><thead><tr><th>상품명</th><th class="num">상품액</th><th class="num">판매수량</th><th class="num">매출 비중</th><th>세부 내역</th></tr></thead><tbody>${rs.map((r,i)=>productRow(r,total,i)).join('')}</tbody></table></div>`}
  function categoryPerformance(list){
    const groups=new Map();for(const r of list){if(!groups.has(r.category))groups.set(r.category,[]);groups.get(r.category).push(r)}
    const ordered=[...groups].sort((a,b)=>sum(b[1],'sales')-sum(a[1],'sales')),total=sum(list,'sales');
    if(!ordered.length)return '<div class="empty">선택 조건에 자료가 없습니다. 검색어나 필터를 변경해 주세요.</div>';
    return `<div class="category-overview-label"><span>${ordered.length}개 카테고리 · 매출순</span><span>카테고리를 펼쳐 상품을 확인하세요</span></div><div class="category-performance">${ordered.map(([name,rs],i)=>{const sales=sum(rs,'sales'),share=total>0?sales/total*100:0;return `<details class="category-performance-card" ${category?'open':''}><summary><div class="category-heading"><span class="category-number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(name)}</h3><small>${nf(rs.length)}개 통합 상품</small></div></div><div class="category-stat"><small>상품액</small><strong>${won(sales)}</strong></div><div class="category-stat category-volume"><small>판매수량</small><b>${nf(sum(rs,'qty'))}개${rs.some(r=>r.unknownQty)?' + 미확인':''}</b></div><div class="category-stat category-ratio"><small>전체 대비</small><b>${share.toFixed(1)}%</b><div class="product-share"><i style="width:${Math.max(0,Math.min(100,share))}%"></i></div></div><span class="category-chevron" aria-hidden="true">⌄</span></summary><div class="category-products"><p class="sub">비중은 현재 검색·채널 조건의 전체 카테고리 상품액 대비입니다. 수량은 확인된 수량만 합산합니다.</p>${productTable(rs,total)}</div></details>`}).join('')}</div>`;
  }
  function render(){
    const raw=rows(),items=filtered(raw),list=group(items).sort((a,b)=>(b[sort]||0)-(a[sort]||0));
    const categories=[...new Set(raw.map(r=>r.category))].sort();
    const coverage=getAnalysis().productCoverage.filter(d=>d>=from&&d<=to);
    page=Math.min(page,Math.max(0,Math.ceil(list.length/40)-1));
    const optionSources=imported().filter(r=>r.kind==='options');
    const partial=kind==='products'?getAnalysis().partialProductDates?.some(d=>d>=from&&d<=to):period==='2026-07-01';
    return `<div class="sales-brandline"><span class="brand-dot"></span>이코복스 이태원점 <span class="badge">상품·옵션 원본 반영</span></div>
    <div class="calendar-toolbar"><a class="btn primary" href="#weekly">위클리 미팅 · 주차별 분석 →</a><div class="segmented"><button data-import-kind="products" class="${kind==='products'?'selected':''}">상품별 판매</button><button data-import-kind="options" class="${kind==='options'?'selected':''}">옵션별 판매</button></div><a class="btn" href="#products?report=legacy">기존 베이커리·젤라또 리포트 ↗</a></div>
    ${kind==='products'?`<div class="calendar-filter product-year-filter"><span class="sub">연도 바로 보기</span>${[2025,2026].map(y=>`<button class="btn small ${from.startsWith(String(y))&&to.startsWith(String(y))?'primary':''}" data-import-year="${y}">${y}년</button>`).join('')}<a class="btn small" href="#dashboard?from=${from}&to=${to}&tab=products&compare=year">선택 상품 전년 비교 →</a><span class="sub">2025년 POS 전체 · 2026년 채널별 확보 범위 확인</span></div>`:''}
    <section class="card"><div class="card-head"><div><h3>${kind==='products'?'상품 판매 분석':'옵션 선택 분석'}</h3><p class="sub">${kind==='products'?'동일 상품을 통합하고 채널별 원본 금액을 함께 보여줍니다. 전체 합계는 중복 대조 전 잠정입니다.':'옵션은 제공된 원본 기간별로 조회합니다.'}</p></div><button class="btn small" id="downloadImport">↓ 조회 원본 CSV</button></div>
    <div class="detail-controls">${kind==='products'?`<div class="range-fields"><label>시작일<input type="date" id="importFrom" value="${from}" aria-label="상품 분석 시작일"></label><span>—</span><label>종료일<input type="date" id="importTo" value="${to}" aria-label="상품 분석 종료일"></label><button class="btn primary" id="applyImport">조회</button></div><a class="btn" href="#dashboard?from=${from}&to=${to}&tab=products">일·주·월 상세 분석 →</a>`:`<label>옵션 원본 기간<select id="optionPeriod" aria-label="옵션 원본 기간">${optionSources.map(s=>`<option value="${s.start}" ${s.start===period?'selected':''}>${s.start} ~ ${s.end}</option>`).join('')}</select></label>`}</div>
    <details class="product-source-note"><summary>집계 기준·자료 상태 확인 <span>일부 채널 대조 중 · 10월 28일 잠정 자료</span></summary><div class="note">${kind==='products'?`${coverage.length}일 POS 원본 · ${esc(channelNote(api.getChannels?.()))} 수량은 주문 건수와 다릅니다. 미확인 수량은 합계에서 제외하고 별도 표시합니다. 환불 열은 POS 원본 별도 표시이며 오터·네이버는 완료 주문 기준입니다.`:'일자 정보가 없는 기간 누적 자료입니다. 일·주·월로 나누지 않으며, 옵션 매출을 상품 실매출에 더하지 않습니다. 총 주문 건수와 선택 비율은 원본 각 행의 값이며, 같은 상품명이 여러 행에 나타나도 임의로 합치지 않습니다.'}${partial?'<br><b>10월 28일 자료는 영업 중 추출한 잠정 집계입니다.</b>':''}</div></details></section>
    <div class="kpis" style="margin:20px 0">${(kind==='products'?[[channel==='all'?'원본 상품액 · 합산 미확정':CHANNELS[channel]+' 상품액',won(sum(items,'sales'))],['판매 수량',nf(sum(items,'qty'))+'개'+(items.some(r=>r.unknownQty)?' + 미확인':'')],['확인 할인액 · 일부 미제공',won(sum(items,'discount'))],['환불 금액 · 별도 표시',won(sum(items,'refund'))]]:[['옵션 매출',won(sum(items,'sales'))],['옵션 선택 건수',nf(sum(items,'selections'))+'건'],['조회 원본 행',nf(items.length)+'행'],['일자별 분석','기간 누적 자료']]).map(([label,value])=>`<div class="card kpi"><div class="kpi-top">${label}</div><div class="kpi-value" style="font-size:24px">${value}</div><div class="kpi-foot">${query||category?'검색·필터 적용':'선택 기간 전체'}</div></div>`).join('')}</div>
    <section class="card"><div class="card-head"><h3>${kind==='products'?(layout==='category'?'카테고리별 판매 실적':'전체 상품 실적'):'옵션 원본 내역'}</h3><span class="sub">${nf(list.length)}${kind==='products'?'개 상품':'행'}</span></div>${kind==='products'?`<div class="product-layout-switch segmented" aria-label="상품 보기 방식"><button data-product-layout="category" class="${layout==='category'?'selected':''}" aria-pressed="${layout==='category'}">카테고리별</button><button data-product-layout="flat" class="${layout==='flat'?'selected':''}" aria-pressed="${layout==='flat'}">전체 상품</button></div>`:''}<div class="detail-controls product-filters"><select id="importChannel" aria-label="상품 원본 채널"><option value="all" ${channel==='all'?'selected':''}>전체 채널 · 잠정 합산</option>${Object.entries(CHANNELS).map(([k,v])=>`<option value="${k}" ${channel===k?'selected':''}>${v}</option>`).join('')}</select><input id="importSearch" aria-label="상품 옵션 검색" placeholder="상품·옵션·카테고리 검색" value="${esc(query)}"><select id="importCategory" aria-label="통합 카테고리"><option value="">전체 카테고리</option>${categories.map(c=>`<option ${category===c?'selected':''} value="${esc(c)}">${esc(c)}</option>`).join('')}</select><select id="importSort" aria-label="원본 정렬">${(kind==='products'?[['sales','실매출순'],['qty','수량순'],['discount','할인순'],['refund','환불순']]:[['sales','옵션 매출순'],['selections','옵션 선택 건수순']]).map(([k,t])=>`<option value="${k}" ${sort===k?'selected':''}>${t}</option>`).join('')}</select></div>
    ${kind==='products'?(layout==='category'?categoryPerformance(list):productTable(list.slice(page*40,page*40+40),sum(list,'sales'))):`<div class="table-wrap"><table><thead><tr>${(kind==='products'?['상품 / 통합 카테고리','상품액','수량','총 매출 · 확인분','할인 · 확인분','환불 금액 / 수량','포인트 / 선불권']:['옵션 / 상품 / 카테고리','판매가','총 주문 건수','옵션 선택 건수','옵션 매출','평균 판매가','선택 비율 / 원본 행']).map((t,i)=>`<th class="${i?'num':''}">${t}</th>`).join('')}</tr></thead><tbody>${list.slice(page*40,page*40+40).map(r=>kind==='products'?`<tr><td><strong>${esc(r.name)}</strong><small class="table-sub">${esc(r.category)} · 관측 ${r.days.size}일</small>${r.names.size>1||r.categories.size>1?`<details class="product-aliases"><summary>통합 원본명 ${r.names.size}개 · 카테고리 ${r.categories.size}개</summary>${[...r.names].map(n=>`<div>${esc(n)}</div>`).join('')}<small>원본 카테고리: ${esc([...r.categories].join(', '))}</small></details>`:''}</td><td class="num"><strong>${won(r.sales)}</strong><small class="table-sub">${Object.entries(r.channels).map(([c,v])=>CHANNELS[c]+' '+won(v)).join('<br>')}</small></td><td class="num">${r.unknownQty?'미확인 포함 · ':''}${nf(r.qty)}</td><td class="num">${r.unknownGross?(r.gross?won(r.gross)+' + 미제공':'미제공'):won(r.gross)}</td><td class="num">${r.unknownDiscount?(r.discount?won(r.discount)+' + 미제공':'미제공'):won(r.discount)}</td><td class="num">${won(r.refund)}<small class="table-sub">${nf(r.refundQty)}개</small></td><td class="num">${won(r.points)} / ${won(r.prepaid)}</td></tr>`:`<tr><td><strong>${esc(r.option)}</strong><small class="table-sub">${esc(r.name)}<br>${esc(r.category)}</small></td><td class="num">${won(r.unitPrice)}</td><td class="num">${nf(r.orderCount)}</td><td class="num">${nf(r.selections)}</td><td class="num">${won(r.sales)}</td><td class="num">${won(r.averagePrice)}</td><td class="num">${esc(r.selectionRate)}<small class="table-sub">엑셀 ${r.sourceRow}행</small></td></tr>`).join('')||'<tr><td colspan="7" class="empty">선택 조건에 자료가 없습니다.</td></tr>'}</tbody></table></div>`}
    ${kind!=='products'||layout==='flat'?`<div class="pagination"><span>${page+1} / ${Math.max(1,Math.ceil(list.length/40))} 페이지</span><div><button class="btn small" id="importPrev" ${page===0?'disabled':''}>이전</button><button class="btn small" id="importNext" ${page>=Math.ceil(list.length/40)-1?'disabled':''}>다음</button></div></div>`:''}</section>
    ${kind==='products'?renderChannelAudit(api.getChannels?.(),{won,esc,nf},auditExpanded):''}
    <details class="card" style="margin-top:20px"><summary>반영한 파일 ${imported().length}개 · 합계 검증과 집계 기준</summary><div class="table-wrap"><table><thead><tr><th>원본</th><th class="num">반영 행</th><th>제공 범위 / 검증</th></tr></thead><tbody>${imported().map(s=>`<tr><td>${esc(s.label)}</td><td class="num">${nf(s.records)}</td><td>${s.start} ~ ${s.end}<small class="table-sub">${s.kind==='products'?'일별 상품 합계와 원본 일자별 합계 일치 · 전체 합계 대조 완료':'누적 옵션 원본 행 전체 보존'}</small></td></tr>`).join('')}</tbody></table></div><p class="sub">원본 카테고리·상품명·금액은 보존하고, 분석 화면에서만 통합 상품 기준을 적용합니다. 통합 원본명은 상품별로 펼쳐 확인할 수 있습니다. 일자에 귀속되지 않은 2026년 상반기 부분 분할결제 수량 5개·총 매출 300원·할인 300원·실매출 0원·환불 22,600원은 별도 보존하며 특정 날짜나 상품에 배분하지 않습니다. 상품 상세 합계와 원본 전체 합계의 차이는 이 별도 행입니다. 총매출 달력의 기존 입력은 보존하고, 새 채널 상품 자료와 월별 검토표를 연결했습니다. 미해결 차이는 원본 전체 검토표를 확인하세요.</p><button class="btn small" id="downloadAdjustments">↓ 부분 분할결제 원본 CSV</button></details>`;
  }
  function exportCSV(name,rs,fields){download(name,'\uFEFF'+[fields.map(x=>x[1]),...rs.map(r=>fields.map(([k])=>(k==='name'?(r.originalName??r.name):k==='category'?(r.originalCategory??r.category):r[k])??''))].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
  function bind(){const audit=document.querySelector('.channel-audit');if(audit)audit.ontoggle=()=>{auditExpanded=audit.open};const on=(id,fn)=>{const el=$('#'+id);if(el)el.onclick=fn};
    $$('[data-product-layout]').forEach(b=>b.onclick=()=>{layout=b.dataset.productLayout;page=0;rerender()});
    $$('[data-import-year]').forEach(b=>b.onclick=()=>{const year=b.dataset.importYear,dates=getAnalysis().productCoverage.filter(d=>d.startsWith(year)).sort();from=dates[0];to=dates.at(-1);query='';category='';page=0;rerender()});
    $$('[data-import-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.importKind;category='';query='';sort='sales';page=0;rerender()});
    on('applyImport',()=>{const a=$('#importFrom').value,b=$('#importTo').value;if(!a||!b||a>b)return api.toast('시작일과 종료일을 확인하세요.');from=a;to=b;category='';page=0;rerender()});
    if($('#optionPeriod'))$('#optionPeriod').onchange=e=>{period=e.target.value;category='';page=0;rerender()};
    if($('#importChannel'))$('#importChannel').onchange=e=>{channel=e.target.value;page=0;rerender()};
    if($('#importCategory'))$('#importCategory').onchange=e=>{category=e.target.value;page=0;rerender()};
    if($('#importSort'))$('#importSort').onchange=e=>{sort=e.target.value;page=0;rerender()};
    if($('#importSearch'))$('#importSearch').oninput=e=>{query=e.target.value;page=0;rerender();$('#importSearch').focus();$('#importSearch').setSelectionRange(query.length,query.length)};
    on('importPrev',()=>{page--;rerender()});on('importNext',()=>{page++;rerender()});
    on('downloadImport',()=>exportCSV(`이코복스_${kind}_원본.csv`,filtered(),kind==='options'?[['store','매장명'],['start','시작일'],['end','종료일'],['option','옵션명'],['category','카테고리명'],['name','상품명'],['unitPrice','판매가'],['orderCount','총 주문 건수'],['selections','옵션 선택 건수'],['sales','옵션 총 매출액'],['averagePrice','옵션 평균 판매가'],['selectionRate','옵션 선택 비율'],['sourceRow','원본 행']]:[['channel','원본 채널'],['unknownQty','수량 미확인'],['date','영업일'],['category','카테고리명'],['name','상품명'],['unitPrice','상품별 단가'],['qty','수량'],['sold','판매량'],['gross','총 매출'],['sales','실매출'],['discount','할인'],['points','포인트 사용'],['prepaid','선불권 사용'],['refund','환불 금액'],['refundQty','환불 수량'],['sourceRow','원본 행']]));
    on('downloadAdjustments',()=>exportCSV('이코복스_부분분할결제.csv',(getAnalysis().productAdjustments||[]).map(r=>({...r,start:imported().find(s=>s.id===r.source)?.start,end:imported().find(s=>s.id===r.source)?.end})),[['start','시작일'],['end','종료일'],['label','구분'],['qty','수량'],['gross','총 매출'],['sales','실매출'],['discount','할인'],['refund','환불 금액'],['refundQty','환불 수량']]));
  }
  return {render,bind};
}
